// =============================================================================
// Message Types - Event Chain Service
// =============================================================================
message GetEventsRequest {
  uint64 from_event_id = 1;
  uint64 to_event_id = 2;
  // Max events to return
  uint32 limit = 3;
  // Filter by plugin
  string plugin_id = 4;
  // Filter by tags
  repeated string tags = 5;
  // Filter by decision
  Decision decision_filter = 6;
}
